#!/bin/bash

python3 -m venv .venv
source .venv/bin/activate

pip3 install pyzmq

export N="10"
BASE_PORT=5555

mkdir -p mix

for run in {1..10}; do
    echo "=== RUN $run ==="

    # Start nodes
    for ((i=0; i<N; i++)); do
        PORT=$((BASE_PORT + i))
        echo "Starting node on port $PORT"
        gnome-terminal -- bash -c "python3 node.py $N $PORT mix; exec bash"
    done
    echo "Waiting 130 seconds before next run..."
    sleep 130

    # Create directory for this run
    mkdir -p mix/$run

    # Copy process logs generated by the nodes
    cp process* mix/$run/

    # Close all the spawned terminals
    killall gnome-terminal-server
done
